    """Recursively reject duplicate object keys at any nesting depth."""
    if isinstance(obj, dict):
        seen = set()
        for key in obj:
            if key in seen:
                raise ValueError("duplicate object key: %r" % (key,))
            seen.add(key)
        for value in obj.values():
            _reject_duplicates(value)
    elif isinstance(obj, list):
        for item in obj:
            _reject_duplicates(item)


def parse_jsonl(text):
    """Parse newline-delimited JSON text into a list of decoded values.

    Whitespace-only lines are skipped. Malformed non-blank JSON lines raise
    ValueError. Duplicate object keys at any nesting depth raise ValueError.
    """
    results = []
    for line in text.splitlines():
        if not line.strip():
            continue
        value = json.loads(line)
        _reject_duplicates(value)
        results.append(value)
    return results

